// V1.11 canonical Chain Identity Registry: one record per network the product can name (routing catalog, custom
// ONEbridge network, active TVL catalog, local test chains). Browser-safe types and pure rules only; the generated
// data lives in chain-identities.generated.json (server/docs) and chain-identities.client.json (compact, loaded
// only by lazy UI chunks). Generated by `pnpm assets:sync:chains` — never edited by hand.
//
// Environment is a SAFETY field: a testnet must never be shown or counted as a mainnet, and a financial route never
// crosses environments silently. When no source decides, the environment is "unknown" (never guessed "mainnet").
export type ChainEnvironment =
  "mainnet" | "testnet" | "devnet" | "local" | "unknown";
export const CHAIN_ENVIRONMENTS: readonly ChainEnvironment[] = [
  "mainnet",
  "testnet",
  "devnet",
  "local",
  "unknown",
];
// Logo priority (first available wins): a verified local asset, the chain's official asset, the exact Trust Wallet
// chain asset (chain-ID mapped), another approved curated source (CoinGecko asset platform, chain-ID mapped), and
// finally the generated Otherbridge monogram. Never a name/symbol match, never a remote URL in the browser.
export type ChainLogoSource =
  "local-verified" | "official" | "trustwallet" | "curated" | "monogram";
export const CHAIN_LOGO_PRIORITY: readonly ChainLogoSource[] = [
  "local-verified",
  "official",
  "trustwallet",
  "curated",
  "monogram",
];
export type ChainEcosystem =
  "EVM" | "SVM" | "UTXO" | "MVM" | "TVM" | "STL" | "OTHER";
export interface ChainIdentity {
  /** Internal id used across the product: the routing/catalog chain id, or `catalog:<slug>` without a chain id. */
  id: string;
  /** Numeric chain id (EIP-155 for EVM; the routing provider's numeric id for non-EVM), null when unknown. */
  chainId: string | null;
  /** CAIP-2 when known (eip155:1, solana:mainnet, bip122:bitcoin …). */
  caip2: string | null;
  name: string;
  shortName: string;
  environment: ChainEnvironment;
  environmentSource:
    | "routing-catalog"
    | "custom-registry"
    | "tvl-catalog"
    | "ethereum-lists"
    | "local-test"
    | "none";
  ecosystem: ChainEcosystem;
  nativeSymbol: string | null;
  explorer: string | null;
  /** Same-origin path of the sanitized logo, or null (monogram). */
  logo: string | null;
  logoSource: ChainLogoSource;
  /** Where the logo came from (URL or repository record) — provenance, not an endorsement. */
  logoProvenance: string;
  logoSha256: string | null;
  sources: string[];
  updatedAt: string;
}
export interface ChainIdentityFile {
  version: 1;
  generatedAt: string;
  note: string;
  chains: ChainIdentity[];
}
/** Compact client record: [environment, logo | "", shortName, explorer | ""]. */
export type ClientChainIdentity = [ChainEnvironment, string, string, string];

const TESTNET_NAME =
  /\b(test ?net|sepolia|goerli|holesky|hoodi|ropsten|rinkeby|kovan|amoy|mumbai|fuji|chiado|alfajores|baklava|shasta|nile|signet|regtest|preview|preprod)\b/i;
const DEVNET_NAME = /\b(devnet|dev ?net|localnet)\b/i;
/** Chain ids the local-test mode uses for its synthetic chains (never a public network). */
export const LOCAL_TEST_CHAINS = new Set(["31337", "31338"]);

// Environment decision, most authoritative source first. Name heuristics may only ever move a chain AWAY from
// "mainnet" (a testnet-looking name is never trusted as mainnet), never toward it.
export function environmentOf(input: {
  id: string;
  name: string;
  routingMainnet?: boolean;
  custom?: boolean;
  tvlPositive?: boolean;
  ethereumListsTestnet?: boolean;
}): Pick<ChainIdentity, "environment" | "environmentSource"> {
  const nameSaysTest = TESTNET_NAME.test(input.name);
  const nameSaysDev = DEVNET_NAME.test(input.name);
  if (LOCAL_TEST_CHAINS.has(input.id))
    return { environment: "local", environmentSource: "local-test" };
  if (input.routingMainnet !== undefined) {
    if (input.routingMainnet && !nameSaysTest && !nameSaysDev)
      return { environment: "mainnet", environmentSource: "routing-catalog" };
    return {
      environment: nameSaysDev ? "devnet" : "testnet",
      environmentSource: "routing-catalog",
    };
  }
  if (input.custom && !nameSaysTest && !nameSaysDev)
    return { environment: "mainnet", environmentSource: "custom-registry" };
  if (nameSaysDev) return { environment: "devnet", environmentSource: "none" };
  if (nameSaysTest || input.ethereumListsTestnet)
    return {
      environment: "testnet",
      environmentSource: input.ethereumListsTestnet ? "ethereum-lists" : "none",
    };
  // The active TVL catalog lists production networks with locked value (testnets are filtered upstream and here).
  if (input.tvlPositive)
    return { environment: "mainnet", environmentSource: "tvl-catalog" };
  return { environment: "unknown", environmentSource: "none" };
}

/** Short display name: an explicit short name, or the name without trailing network words. */
export function shortNameOf(name: string, explicit?: string | null) {
  const clean = (explicit ?? "").trim();
  if (clean && clean.length <= 16 && /^[\p{L}\p{N} .-]+$/u.test(clean))
    return clean;
  const base = name
    .replace(/\s+(mainnet|network|chain|smart chain)$/i, "")
    .trim();
  if (base.length <= 16) return base;
  // Cut at a word boundary (never mid-word); a single over-long word is shortened with an ellipsis.
  const words: string[] = [];
  for (const w of base.split(/\s+/)) {
    if ([...words, w].join(" ").length > 16) break;
    words.push(w);
  }
  return words.length ? words.join(" ") : `${base.slice(0, 15)}…`;
}

/** Mainnet ⇄ testnet (or any environment mismatch) is never a silent financial route. */
export function crossEnvironment(
  a: ChainEnvironment | undefined,
  b: ChainEnvironment | undefined,
) {
  return !a || !b || a !== b || a === "unknown";
}

/** Monogram letters for the generated fallback mark (no external asset, no colour claim). */
export function monogram(name: string) {
  const words = name
    .replace(/[^\p{L}\p{N} ]/gu, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  const letters =
    words.length >= 2
      ? words[0][0] + words[1][0]
      : (words[0] ?? "?").slice(0, 2);
  return letters.toLocaleUpperCase("en");
}
